/**
 * ScheduleModalService — グローバル「予定調整」モーダル管理
 *
 * 仕様:
 *   - 全ページ共通で使える単一の開閉状態 (BehaviorSubject)
 *   - `open()` を呼ぶとモーダルが開き、`close()` で閉じる
 *   - モーダル本体のテンプレートは AppComponent が購読して描画する
 *     (schecon.com/history の 予定調整ピッカーと同一デザイン)
 *   - ページから呼ぶ場合は DI して `scheduleModal.open()` とするだけ
 *
 * ユーザー指示 (2026-04-21):
 *   TOP ページ以下のディレクトリー内で
 *   「予定調整をする」「予定調整」のアイコン/メニューを押したとき
 *   schecon.com/history 準拠のモーダルを立ち上げる
 */
import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class ScheduleModalService {
  private readonly _isOpen$ = new BehaviorSubject<boolean>(false);
  readonly isOpen$: Observable<boolean> = this._isOpen$.asObservable();

  /** 現在の開閉状態 (同期取得) */
  get isOpen(): boolean {
    return this._isOpen$.value;
  }

  /** モーダルを開く */
  open(): void {
    if (!this._isOpen$.value) {
      this._isOpen$.next(true);
    }
  }

  /** モーダルを閉じる */
  close(): void {
    if (this._isOpen$.value) {
      this._isOpen$.next(false);
    }
  }

  /** 開閉トグル */
  toggle(): void {
    this._isOpen$.next(!this._isOpen$.value);
  }
}
